#include "postquantiquecoin/core/ErrorCode.h"
namespace pqc { const char* ErrorCodeName(ErrorCode c){ switch(c){ case ErrorCode::Ok:return "Ok"; case ErrorCode::InvalidBlock:return "InvalidBlock"; case ErrorCode::InvalidTransaction:return "InvalidTransaction"; case ErrorCode::InvalidSignature:return "InvalidSignature"; case ErrorCode::InvalidAddress:return "InvalidAddress"; case ErrorCode::StorageError:return "StorageError"; case ErrorCode::CryptoError:return "CryptoError"; case ErrorCode::NetworkError:return "NetworkError"; case ErrorCode::WalletLocked:return "WalletLocked"; case ErrorCode::WalletCorrupted:return "WalletCorrupted"; case ErrorCode::InsufficientFunds:return "InsufficientFunds"; case ErrorCode::ConsensusError:return "ConsensusError"; case ErrorCode::SerializationError:return "SerializationError"; case ErrorCode::CorruptionDetected:return "CorruptionDetected"; case ErrorCode::PowInvalid:return "PowInvalid"; case ErrorCode::MempoolRejected:return "MempoolRejected"; case ErrorCode::UnauthorizedSpend:return "UnauthorizedSpend"; } return "Unknown"; } }
